class Solution {
    public int digits(int num){
        if(num==0)return 0;
        int ld=num%10;
        return ld+digits(num/10);
    }
    public int addDigits(int num) {
        //your code goes here
        int ans=digits(num);
        while(ans>9){
            ans=digits(ans);
        }
        return ans;
    }
}
